import { Component, computed, inject, signal } from '@angular/core';
import { Figures } from '../../core/figures';
import { Rates, money } from '../../core/rates';
import { Session } from '../../core/session';

// The sheet's rates for each grade: one form sets a grade's rate from a date (or from the beginning
// of time) through a to-date (or for good), one table shows each grade's rate in force on the sheet's today, or n/a when none
// applies, a calendar shows each grade's rate in force on the first day of each month of the sheet's
// today's calendar year, and another lists every rate with its from- and to-date. A preview shows how many open and
// pending claims of a grade a candidate rate would change, and by how much; it saves nothing.
@Component({
  selector: 'app-rates',
  template: `
    <section aria-label="Rates" data-testid="rates">
      <h2>Rates</h2>
      <form (submit)="submit($event)" data-testid="rate-form">
        <label for="rate-form-grade">Grade</label>
        <select
          id="rate-form-grade"
          data-testid="rate-form-grade"
          [value]="grade()"
          (change)="grade.set(value($event)); error.set(null)"
        >
          @for (g of grades(); track g) {
            <option [value]="g" [selected]="g === grade()">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input
          id="rate-form-pct"
          data-testid="rate-form-pct"
          inputmode="decimal"
          [value]="pct()"
          (input)="pct.set(value($event)); error.set(null)"
        />
        <label for="rate-form-from">From (YYYY-MM-DD, blank for always)</label>
        <input
          id="rate-form-from"
          data-testid="rate-form-from"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <label for="rate-form-to">To (YYYY-MM-DD, blank for no end)</label>
        <input
          id="rate-form-to"
          data-testid="rate-form-to"
          [value]="to()"
          (input)="to.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="rate-form-submit" [disabled]="saving()">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
        }
      </form>
      <form (submit)="preview($event)" data-testid="rate-preview-form" aria-label="Rate preview">
        <label for="rate-preview-grade">Preview grade</label>
        <select
          id="rate-preview-grade"
          data-testid="rate-preview-grade"
          [value]="previewGrade()"
          (change)="previewGrade.set(value($event)); clearPreview()"
        >
          @for (g of grades(); track g) {
            <option [value]="g" [selected]="g === previewGrade()">{{ g }}</option>
          }
        </select>
        <label for="rate-preview-pct">Candidate rate (%)</label>
        <input
          id="rate-preview-pct"
          data-testid="rate-preview-pct"
          inputmode="decimal"
          [value]="previewPct()"
          (input)="previewPct.set(value($event)); clearPreview()"
        />
        <button type="submit" data-testid="rate-preview">Preview</button>
        @if (previewed(); as r) {
          <p>
            Claims changed <span data-testid="rate-preview-count">{{ r.count }}</span>,
            difference <span data-testid="rate-preview-diff">{{ r.diff }}</span>
          </p>
        }
        @if (previewError(); as err) {
          <p role="alert" data-testid="rate-preview-error">{{ err }}</p>
        }
      </form>
      <table data-testid="rate-today">
        <caption>In force today</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate (%)</th></tr>
        </thead>
        <tbody>
          @for (g of grades(); track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ rates.current(g) }}</td>
            </tr>
          }
        </tbody>
      </table>
      @if (months().length) {
        <table data-testid="rate-calendar">
          <caption>On the first of each month</caption>
          <thead>
            <tr>
              <th scope="col">Grade</th>
              @for (m of months(); track m) {
                <th scope="col">{{ m }}</th>
              }
            </tr>
          </thead>
          <tbody>
            @for (g of grades(); track g) {
              <tr>
                <th scope="row">{{ g }}</th>
                @for (m of months(); track m) {
                  <td [attr.data-testid]="'rate-month-' + g + '-' + m">{{ rates.onDate(g, m + '-01') }}</td>
                }
              </tr>
            }
          </tbody>
        </table>
      }
      <table data-testid="rate-list">
        <caption>All rates</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Rate (%)</th><th scope="col">Versions</th></tr>
        </thead>
        <tbody>
          @for (r of rates.rates(); track r.grade + '-' + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? 'always' }}</td>
              <td data-testid="rate-to">{{ r.to ?? '' }}</td>
              <td><span data-testid="rate-pct">{{ r.rate }}</span></td>
              <td data-testid="rate-version">{{ r.version }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class RatesPanel {
  protected readonly rates = inject(Rates);
  private readonly figures = inject(Figures);
  private readonly session = inject(Session);
  protected readonly grades = this.session.grades;
  protected readonly grade = signal<string>('A');
  protected readonly pct = signal('');
  protected readonly from = signal('');
  protected readonly to = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** The months (YYYY-MM) of the sheet's today's calendar year; none before a today is known. */
  protected readonly months = computed(() => {
    const year = this.session.shownToday()?.slice(0, 4);
    return year ? Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`) : [];
  });

  protected readonly previewGrade = signal<string>('A');
  protected readonly previewPct = signal('');
  protected readonly previewed = signal<{ count: number; diff: string } | null>(null);
  protected readonly previewError = signal<string | null>(null);

  protected clearPreview(): void {
    this.previewed.set(null);
    this.previewError.set(null);
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement | HTMLSelectElement).value;
  }

  protected async submit(e: Event): Promise<void> {
    e.preventDefault();
    if (this.saving()) return; // a second submit before the first has answered
    this.error.set(null);
    this.saving.set(true);
    try {
      const err = await this.rates.set(this.grade(), this.pct(), this.from(), this.to());
      if (err) this.error.set(err);
      else {
        this.pct.set('');
        this.from.set('');
        this.to.set('');
      }
    } finally {
      this.saving.set(false);
    }
  }

  protected preview(e: Event): void {
    e.preventDefault();
    this.clearPreview();
    const pct = this.previewPct().trim();
    if (!/^\d+(\.\d{1,2})?$/.test(pct)) {
      this.previewError.set('Enter a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    const r = this.figures.ratePreview(this.previewGrade(), pct);
    // shown after a tick, so two presses with the same result can be told apart
    setTimeout(() => this.previewed.set({ count: r.count, diff: money(r.diffCents) }));
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, isDate } from './session';

export interface Rate {
  grade: string;
  /** The first day the rate applies (YYYY-MM-DD); null when it applies from the beginning of time. */
  from: string | null;
  /** The last day the rate applies (YYYY-MM-DD); null when it applies on for good. */
  to: string | null;
  /** A percent with two decimals, as the server stores it. */
  rate: string;
  /** How many versions the rate has had; the one shown is the newest. */
  version: number;
  /** What the claims already on the sheet when a forward-only version was saved use instead, oldest first. */
  earlier?: Earlier[];
}

/** The claims whose id is at most `upTo` (and above the entry before's) use this rate (null: none of this
 *  grade and from-date) through this to-date (null: for good). */
export interface Earlier {
  upTo: number;
  rate: string | null;
  to: string | null;
}

/** What due shows for a grade with no rate. */
export const NO_RATE = 'n/a';

// The active sheet's rates for each grade, re-read from the server each time the sheet is loaded.
// A grade may have several, each from a date; on a date the one in force is the one whose from-date
// is the latest on or before it, a rate with no from-date applying from the beginning of time; none
// is in force when the date is after that rate's to-date. A grade with none in force on a date takes the
// one in force then on the sheet's parent, then the parent's parent, up to three levels up.
// A rate saved with a from-date on or after the sheet's today is forward-only: a claim already on the
// sheet then keeps what applied to it (its `earlier` entries), the rate applying to those added later.
// Due is worked out in whole cents and hundredths of a percent, with BigInt, so it is exact.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** By grade, then from-date, the one with none first. */
  readonly rates = signal<Rate[]>([]);
  /** The rates of each of the sheet's ancestors, its parent first, each by grade then from-date. */
  readonly inherited = signal<Rate[][]>([]);
  private loads = 0;

  /** The grade's rate in force on a date (YYYY-MM-DD) on the sheet, else on the nearest ancestor with one,
   *  or undefined when none applies. */
  inForce(grade: string, date: string): Rate | undefined {
    for (const rates of [this.rates(), ...this.inherited()]) {
      const found = inForceAmong(rates, grade, date);
      if (found) return found;
    }
    return undefined;
  }

  /** The grade's rate in force on a date for a claim (by id; none: one added now), each rate as it applies
   *  to that claim; undefined when none applies. */
  inForceFor(grade: string, date: string, claimId?: number): Rate | undefined {
    if (claimId === undefined) return this.inForce(grade, date);
    for (const rates of [this.rates(), ...this.inherited()]) {
      const found = inForceAmong(forClaim(rates, claimId), grade, date);
      if (found) return found;
    }
    return undefined;
  }

  /** A grade's rate in force on the sheet's today, with two decimals, or n/a when it has none. */
  current(grade: string): string {
    const today = this.session.shownToday();
    return (today ? this.inForce(grade, today)?.rate : undefined) ?? NO_RATE;
  }

  /** A grade's rate in force on a date (YYYY-MM-DD), with two decimals, or n/a when it has none. */
  onDate(grade: string, date: string): string {
    return this.inForce(grade, date)?.rate ?? NO_RATE;
  }

  /** An amount in cents times the grade's rate in force on a date, divided by 100, rounded to cents as
   *  a claim dated `roundOn` rounds (half up before the policy date, else half to even): the rate figure,
   *  before any late charge or floor; null when no rate of the grade applies then. Given a claim's id, each
   *  rate as it applies to that claim. */
  dueCents(amountCents: bigint, grade: string, date: string, roundOn: string = date, claimId?: number): bigint | null {
    const rate = this.inForceFor(grade, date, claimId);
    if (rate === undefined) return null;
    return rounded(amountCents * hundredths(rate.rate), 10000n, this.session.roundsHalfUp(roundOn));
  }

  /** An amount written with two decimals times the grade's rate on a date, as `dueCents`, shown
   *  with two decimals or n/a. */
  due(amount: string, grade: string, date: string): string {
    const d = this.dueCents(hundredths(amount), grade, date);
    return d === null ? NO_RATE : money(d);
  }

  /** Re-read the active sheet's rates from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.rates.set([]);
    this.inherited.set([]);
    if (!user || !sid) return null;
    try {
      const [rates, inherited] = await Promise.all([
        firstValueFrom(this.http.get<Rate[]>(this.url(sid), { headers: { 'X-User': user } })),
        firstValueFrom(this.http.get<Rate[][]>(`${this.url(sid)}/inherited`, { headers: { 'X-User': user } })),
      ]);
      if (load === this.loads) {
        this.rates.set([...rates].sort(byGradeAndFrom));
        this.inherited.set(inherited.map((level) => [...level].sort(byGradeAndFrom)));
      }
      return null;
    } catch (e) {
      return failed('load', e).replace(' rate', ' rates');
    }
  }

  /** Set a grade's rate from a date (blank: from the beginning of time) through a to-date (blank:
   *  for good), replacing the one it had from that date; an error message when refused. */
  async set(grade: string, pct: string, from: string, to: string): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    if (!/^\d+(\.\d{1,2})?$/.test(pct.trim())) return 'Enter a rate of 0.00 or more, with up to two decimals.';
    if (from.trim() && !isDate(from.trim())) return 'Enter a from-date as YYYY-MM-DD, or leave it blank.';
    if (to.trim() && !isDate(to.trim())) return 'Enter a to-date as YYYY-MM-DD, or leave it blank.';
    if (to.trim() && from.trim() && to.trim() < from.trim()) return "A rate's to-date cannot be before its from-date.";
